    fun getStoriesByGrade(grade: Int): List<ComprehensionStory> {
        return stories.filter { it.grade == grade }
    }

    fun getRandomStory(grade: Int): ComprehensionStory? {
        val list = getStoriesByGrade(grade)
        if (list.isEmpty()) return null
        return list.random()
    }
